<template>
    <div class="layout-px-spacing">  
            <ul class="navbar-nav flex-row mt-2">
                <li>
                    <div class="page-header">
                        <nav class="breadcrumb-one" aria-label="breadcrumb">
                            <ol class="breadcrumb">
                                <li class="breadcrumb-item"><a href="javascript:;">Projects</a></li>
                                <li class="breadcrumb-item active" aria-current="page"><span>Planning</span></li>
                            </ol>
                        </nav>
                    </div>
                </li>
            </ul>


        <h5 class="text-center"> {{ project?.short_name }} PROJECT EXPENDITURES</h5>

        <!-- offcanvas start -->
<div class="offcanvas offcanvas-end" data-bs-scroll="true" tabindex="-1" id="offcanvasWithBothOptions" aria-labelledby="offcanvasWithBothOptionsLabel">
  <div class="offcanvas-header">
    <h5 class="offcanvas-title" id="offcanvasWithBothOptionsLabel">PROJECT LISTS</h5>
    <button type="button" class="btn-close" data-bs-dismiss="offcanvas" aria-label="Close"></button>
  </div>
  <div class="offcanvas-body">
  <div class="row">
  <div class="col-12">
 <div
  class="list-group"
  id="list-tab"
  role="tablist"
  v-bind="mobileView ? {
    'data-bs-toggle': 'offcanvas',
    'data-bs-target': '#budgetOffcanvas',
    'aria-controls': 'budgetOffcanvas'
  } : {}"
>

      <a v-for="projectList in projects" :key="projectList.id" class="list-group-item list-group-item-action" :id="'project-link-' + projectList.id" data-bs-toggle="list" :href="'#project-' + projectList.id" role="tab" :aria-controls="'project-' + projectList.id" @click="project = projectList" data-bs-dismiss="offcanvas">{{ projectList.short_name }}</a>
    </div>
  </div>
</div>
  </div>
</div>
 <!-- offcanvas ends -->

        <div class="d-flex">
            <div class="ms-auto ">

                 <button class="btn" v-if="mobileView"  data-bs-toggle="offcanvas" data-bs-target="#offcanvasWithBothOptions" aria-controls="offcanvasWithBothOptions">
    <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" fill="currentColor" class="bi bi-list-ul" viewBox="0 0 16 16">
  <path fill-rule="evenodd" d="M5 11.5a.5.5 0 0 1 .5-.5h9a.5.5 0 0 1 0 1h-9a.5.5 0 0 1-.5-.5m0-4a.5.5 0 0 1 .5-.5h9a.5.5 0 0 1 0 1h-9a.5.5 0 0 1-.5-.5m0-4a.5.5 0 0 1 .5-.5h9a.5.5 0 0 1 0 1h-9a.5.5 0 0 1-.5-.5m-3 1a1 1 0 1 0 0-2 1 1 0 0 0 0 2m0 4a1 1 0 1 0 0-2 1 1 0 0 0 0 2m0 4a1 1 0 1 0 0-2 1 1 0 0 0 0 2"/>
</svg>
</button>
<button v-else class="btn btn-outline-primary" type="button" data-bs-toggle="offcanvas" data-bs-target="#offcanvasWithBothOptions" aria-controls="offcanvasWithBothOptions">Select Project from the lists</button>

            </div>
        </div>
            <div class="text-center mt-5" v-if="!project">
            <p>Select Project to view it's expenditures</p>
    </div>
    <div class="text-center">
    <span v-if="loading_spinner" v-html="waitIndicator()"></span>
    </div>            



        <!-- plans list starts -->
<div class="row">
<div class="col-2" v-if="!mobileView">
    <div v-if="project" class="list-group" id="list-tab" role="tablist" style="max-height:600px; overflow-y:auto;">
        <div class="d-flex">
            <p>BUDGETS</p>
        </div>
        <a  class="list-group-item list-group-item-action" :id="'project-link-'" data-bs-toggle="list" :href="'#budget-'" role="tab" :aria-controls="'budget-'" @click.prevent="analyseProject()">PROJECT PLAN ANALYSIS</a>
        <a v-for="budget in budgets" :key="budget.id" class="list-group-item list-group-item-action" :id="'project-link-' + budget.id" data-bs-toggle="list" :href="'#budget-' + budget.id" role="tab" :aria-controls="'budget-' + budget.id" @click.prevent="selectBudget(budget)">{{ budget.name }} </a>
    </div>
</div>
  <div class="col-10">
<div class="tab-content" id="nav-tabContent">
  <div
    v-if="project"
    class="tab-pane fade show active"
    :id="'project-' + project.id"
    role="tabpanel"
    :aria-labelledby="'project-link-' + project.id"
  >
    <!-- project tab starts -->


   <div class="panel-body pill-justify-centered tabs">
 
       <ul class="nav nav-pills mb-3 mt-3 justify-content-center" id="justify-center-pills-tab" role="tablist">
        <li class="nav-item">
          <a
          v-if="selectedBudget"
            class="nav-link active"
            id="justify-center-pills-details-tab"
            data-bs-toggle="pill"
            href="#justify-center-pills-details"
            role="tab"
            aria-controls="justify-center-pills-details"
            aria-selected="true"
            @click="triggerPresentBudget()"
          >
           BUDGET ANALYSIS
          </a>

            <a
          v-else
            class="nav-link active"
            id="justify-center-pills-details-tab"
            data-bs-toggle="pill"
            href="#justify-center-pills-details"
            role="tab"
            aria-controls="justify-center-pills-details"
            aria-selected="true"
          >
           PROJECT PLAN ANALYSIS
          </a>
        </li>
         <li v-for="item in selectedBudget.items" class="nav-item" @click="selectedItem = item">
          <a
            class="nav-link "
            id="justify-center-pills-details-tab"
            data-bs-toggle="pill"
            href="#justify-center-pills-details"
            role="tab"
            aria-controls="justify-center-pills-details"
            aria-selected="true"
          >
            {{ item.name }}
          </a>
        </li>
      </ul>

      <div class="tab-content" id="justify-center-pills-tabContent">

        <!-- PROJECT DETAILS -->
        <div
          class="tab-pane fade show active"
          id="justify-center-pills-details"
          role="tabpanel"
          aria-labelledby="justify-center-pills-details-tab"
        >
          <!-- <h4 class="mb-4">Project Plan Details!</h4> -->
<!-- chart starts -->
<div class="w-100">
  <vue-apex-charts
    width="100%"
    :height="chartHeight"
    type="bar"
    :options="budget_list"
    :series="budget_cost"
  />
</div>
<!-- chart ends -->

        </div>
      </div>
    </div>



  </div>

  <div v-else class="tab-pane">No project selected</div>
</div>

  </div>
</div>
         <!-- plans list ends -->
          <!-- budgets footer starts -->
           <div class="text-center fixed-bottom mb-5" v-if="mobileView && project">
            <div class="row">
                <div class="col"></div>
                <div class="col">
             <div class="text-nowrap btn btn-info" style="border-top-left-radius: 80px;border-top-right-radius: 80px;"
              v-bind="mobileView ? {
    'data-bs-toggle': 'offcanvas',
    'data-bs-target': '#budgetOffcanvas',
    'aria-controls': 'budgetOffcanvas'
  } : {}"
             >
                Select Budget
             </div>
                </div>
                <div class="col"></div>
            </div>
           </div>
           <!-- budgets footer ends -->

            <!-- budgets offcanvas start -->
<div class="offcanvas offcanvas-bottom" data-bs-scroll="true" tabindex="-1" id="budgetOffcanvas" aria-labelledby="budgetOffcanvasLabel">
  <div class="offcanvas-header">
    <h5 class="offcanvas-title" id="budgetOffcanvasLabel">BUDGET LISTS</h5>
    <button type="button" class="btn-close" data-bs-dismiss="offcanvas" aria-label="Close"></button>
  </div>
  <div class="offcanvas-body">
  <div class="row">
  <div class="col-12">
    <div class="list-group" id="list-tab" role="tablist">
        <a v-if="!loading_spinner"  class="list-group-item list-group-item-action" :id="'project-link-'" data-bs-toggle="list" :href="'#budget-'" role="tab" :aria-controls="'budget-'" @click.prevent="analyseProject()">PROJECT PLAN ANALYSIS</a>
        <a v-for="budget in budgets" :key="budget.id" class="list-group-item list-group-item-action" :id="'project-link-' + budget.id" data-bs-toggle="list" :href="'#budget-' + budget.id" role="tab" :aria-controls="'budget-' + budget.id" @click.prevent="selectBudget(budget)">{{ budget.name }} </a>      <span v-if="loading_spinner" v-html="waitIndicator()"></span>
    </div>
  </div>
</div>
  </div>
</div>
 <!-- budgets offcanvas ends -->
    </div>
</template>

<script setup>
    import { onMounted, ref ,watch, inject,computed } from 'vue';
    import axios from 'axios';
    import { useMeta } from '@/composables/use-meta';
    useMeta({ title: 'Custom Table' });
    import '@suadelabs/vue3-multiselect/dist/vue3-multiselect.css';
    import VueApexCharts from 'vue3-apexcharts';
    const waitIndicator = inject('waitIndicator');
const axiosInstance = axios.create({
    baseURL: process.env.VUE_APP_API_BASE_URL
});
const project = ref('')

const showError = inject('showError');    
const showMessage = inject('showMessage');   
const loading_spinner = ref(false);
const formatNumber = inject('formatNumber');

const selectedBudget = ref('')


const budget_list = ref({
    chart: { toolbar: { show: false } },
    colors: ['#008FFB', '#FF9800', '#00E396'],
    dataLabels: {
        enabled: true,
        formatter: function (val) {
            if (val >= 1000000) {
                return (val / 1000000).toFixed(1) + 'M';
            } else if (val >= 1000) {
                return (val / 1000).toFixed(1) + 'K';
            }
            return val.toString();
        },
        style: { fontSize: '12px', colors: ['#304758'] },
        offsetX: 0
    },
    plotOptions: {
        bar: {
            horizontal: true,
            barHeight: '70%',
            dataLabels: {
                position: 'top'
            }
        }
    },
    xaxis: { 
        categories: [],
        title: { text: 'Budgets' },
        labels: {
            style: { fontSize: '12px' },
            trim: false,
            maxWidth: 500
        }
    },
    yaxis: {
        title: { text: 'Budget Cost' },
        labels: {
            formatter: function (val) {
                if (val >= 1000000) {
                    return (val / 1000000).toFixed(1) + 'M';
                } else if (val >= 1000) {
                    return (val / 1000).toFixed(1) + 'K';
                }
                return val.toString();
            }
        }
    },
    tooltip: {
        y: {
            formatter: function (val) {
                return formatNumber(val);
            }
        }
    },
    legend: {
        show: true,
        position: 'top'
    }
});

const BAR_HEIGHT = 45; // px per bar row
const chartHeight = computed(() => {
  return Math.max(
    budget_list.value.xaxis.categories.length * BAR_HEIGHT,
    400
  );
});


const budget_cost = ref([
    { name: 'Budget Cost', data: [] },
    { name: 'Used Cost', data: [] },
    { name: 'BOQ Cost', data: [] } 
]);

watch(project, async (newVal) => {
    // Clear chart data completely
    budget_cost.value = [
        { name: 'Budget Cost', data: [] },
        { name: 'Used Cost', data: [] },
        { name: 'BOQ Cost', data: [] }
    ];

    budget_list.value = {
        ...budget_list.value,
        xaxis: { 
            ...budget_list.value.xaxis,
            categories: [],
            title: { text: 'Project Budgets' }
        },
    };

    selectedBudget.value = '';
    selectedItem.value = '';
    
    if (!newVal) return;

    loading_spinner.value = true;
    try {
        const response = await axiosInstance.get(`budgets?project_id=${newVal.id}`);
        budgets.value = response.data;
        
        // Automatically show project-level analysis when project is selected
        analyseProject();
        
    } catch (error) {
        showError && showError(error.message);
        console.error(error);
    } finally {
        loading_spinner.value = false;
    }
});

watch(selectedBudget, async (newVal) => {
        const names = newVal.items.map(b => b.name ?? '');
        const costs = newVal.items.map(b => {
            const v = Number(b.total_budget_items_cost);
            return isNaN(v) ? 0 : v;
        });
        const usedCosts =  newVal.items.map(b => {
            const v = Number(b.total_used_cost ?? b.used_cost ?? 0);
            return isNaN(v) ? 0 : v;
        });

        budget_list.value = {
            ...budget_list.value,
            xaxis: { 
                ...budget_list.value.xaxis,
                categories: names,
                title: { text: 'Budget Items' }
            },
        };

        budget_cost.value = [
            { name: 'Budget Item Cost', data: costs },
            { name: 'Budget Item Used Cost', data: usedCosts }
        ];

});


const selectedItem = ref('')
watch(selectedItem, async (newVal) => {
    if (!newVal || !newVal.descriptions) return;

    const sortedDescriptions = [...newVal.descriptions]
        .sort((a, b) => (b.total_budget_item_description_cost || 0) - (a.total_budget_item_description_cost || 0))
        .slice(0, 10);

    const names = sortedDescriptions.map(b => b.name ?? '');
    const costs = sortedDescriptions.map(b => {
        const v = Number(b.total_budget_item_description_cost);
        return isNaN(v) ? 0 : v;
    });
    const usedCosts = sortedDescriptions.map(b => {
        const v = Number(b.total_used_cost ?? b.used_cost ?? 0);
        return isNaN(v) ? 0 : v;
    });

    budget_list.value = {
        ...budget_list.value,
        xaxis: { 
            ...budget_list.value.xaxis,
            categories: names,
            title: { text: 'Single Item Statement' }
        },
    };
    budget_cost.value = [
        { name: 'Item Statement Cost', data: costs },
        { name: 'Item Statement Used Cost', data: usedCosts }
    ];
});



    const projects = ref([]);
    const getProjects = () => {
        loading_spinner.value = true;
        axiosInstance.get('/projects').then((response) => {
            projects.value = response.data
            .filter(item => item.contracted === 'YES')
            .filter(item => item.status === 'active')
        }).finally(() => {
            loading_spinner.value = false;
        });
    };

    const budgets = ref([])




     const updateBudgetChart = (budget) => {
        if (!budget) return;
        
        const names = budget.items.map(b => b.name ?? '');
        const costs = budget.items.map(b => {
            const v = Number(b.total_budget_items_cost);
            return isNaN(v) ? 0 : v;
        });
        const usedCosts = budget.items.map(b => {
            const v = Number(b.total_used_cost ?? 0);
            return isNaN(v) ? 0 : v;
        });

        budget_list.value = {
            ...budget_list.value,
            xaxis: { 
                ...budget_list.value.xaxis,
                categories: names,
                title: { text: 'Budget Items' }
            },
        };
        budget_cost.value = [
            { name: 'Budget Item Cost', data: costs },
            { name: 'Budget Item Used Cost', data: usedCosts }
        ];
    };

    const triggerPresentBudget = () => {
        if (selectedBudget.value) {
            updateBudgetChart(selectedBudget.value);
        }
    };

const analyseProject = () => {
    selectedBudget.value = '';
    selectedItem.value = ''; 
    if (project.value && budgets.value.length > 0) {
        const names = budgets.value.map(b => b.name ?? '');
        const costs = budgets.value.map(b => {
            const v = Number(b.total_cost);
            return isNaN(v) ? 0 : v;
        });
        const usedCosts = budgets.value.map(b => {
            const v = Number(b.total_used_cost ?? b.used_cost ?? 0);
            return isNaN(v) ? 0 : v;
        });
        const boqCosts = budgets.value.map(b => {
            const v = Number(b.boq_cost ?? 0); // Get BOQ cost from budget data
            return isNaN(v) ? 0 : v;
        });

        budget_list.value = {
            ...budget_list.value,
            xaxis: { 
                ...budget_list.value.xaxis,
                categories: names,
                title: { text: 'Project Budgets' }
            },
        };
        budget_cost.value = [
            { name: 'BOQ Cost', data: boqCosts } ,
            { name: 'Budget Cost', data: costs },
            { name: 'Used Cost', data: usedCosts }
        ];
    }
};

    const selectBudget = (budget) => {
        selectedBudget.value = budget;
        updateBudgetChart(budget);
    };
;

        const mobileView = ref(false)
    const toggleMobileView = () => {
        if (window.innerWidth < 991) {
           mobileView.value = true 
        }
    };

    onMounted(() => {
        toggleMobileView()
        getProjects();
    });
</script>
